import { mkdirSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';

/** Collect emitted application and worker modules, not every installed build dependency. */
export function createLicenseInventory({ projectRoot, outputFile }) {
  const root = path.resolve(projectRoot);
  const modules = new Set();

  function collect(_options, bundle) {
    for (const output of Object.values(bundle)) {
      if (output.type !== 'chunk') continue;
      for (const moduleId of Object.keys(output.modules)) {
        if (moduleId.startsWith('\0')) continue;
        const filename = moduleId.split('?')[0];
        if (!filename.replaceAll('\\', '/').includes('/node_modules/')) continue;
        const relative = path.relative(root, filename);
        if (relative.startsWith('..' + path.sep) || path.isAbsolute(relative)) {
          throw new Error('Bundled dependency is outside the npm project: ' + filename);
        }
        modules.add(relative.split(path.sep).join('/'));
      }
    }
  }

  return {
    mainPlugin: {
      name: 'rdf4j-license-bundle-inventory',
      apply: 'build',
      buildStart() {
        modules.clear();
        rmSync(outputFile, { force: true });
      },
      generateBundle: collect,
      writeBundle() {
        mkdirSync(path.dirname(outputFile), { recursive: true });
        const temporary = outputFile + '.tmp';
        writeFileSync(temporary, JSON.stringify([...modules].sort(), null, 2) + '\n');
        renameSync(temporary, outputFile);
      },
    },
    // Vite runs a separate build for each worker. They contribute before the main bundle is written.
    workerPlugin() {
      return { name: 'rdf4j-worker-license-bundle-inventory', apply: 'build', generateBundle: collect };
    },
  };
}
